<?php
declare(strict_types=1);namespace App\Tests\Imperium\Runtime;use App\Bootstrap\CanonicalJson;use App\Imperium\Runtime\Foundry\SubordinatePersonaSpecificationCognitionGateway;use App\Imperium\Runtime\Foundry\SubordinatePersonaSpecificationService;use PHPUnit\Framework\TestCase;
final class SubordinatePersonaSpecificationServiceTest extends TestCase{public function testArtificerSealsBoundedSpecificationWithoutDownstreamAuthority():void{$root=sys_get_temp_dir().'/imperium-subordinate-spec-'.bin2hex(random_bytes(6));$id='subordinate-construction-case-'.str_repeat('a',20);$requirements=['required_specializations'=>['evidence research'],'seat_requirements'=>['versioned Seat'],'stop_conditions'=>['scope exceeded']];$case=['schema'=>'imperium.foundry-subordinate-construction-case/v1','case_id'=>$id,'instance_id'=>'imperium-test','originating_guildhall_commission_id'=>'guildhall-subordinate-construction-commission-cccccccccccccccccccc','originating_guildhall_commission_digest'=>'guildhall-commission-digest','queue_position'=>1,'office'=>'hagiography','subordinate_staff_class'=>'Chronicler','source_resolution_id'=>'resolution','source_resolution_digest'=>'digest','artificer'=>['manifestation_id'=>'artificer'],'subordinate_requirements'=>$requirements,'status'=>'OPEN_PENDING_PERSONA_SPECIFICATION','construction_authority'=>true,'persona_selection_authority'=>false,'profile_approval_authority'=>false,'spawning_authority'=>false,'admission_authority'=>false,'seat_binding_authority'=>false,'execution_authority'=>false];$case['record_digest']=hash('sha256',CanonicalJson::encode($case));$dir=$root.'/var/imperium/offices/foundry/subordinate-construction-cases';mkdir($dir,0770,true);file_put_contents($dir.'/'.$id.'.json',json_encode($case,JSON_THROW_ON_ERROR));$gateway=new class implements SubordinatePersonaSpecificationCognitionGateway{public function specify(array$case):array{return['disposition'=>'PERSONA_SPECIFICATION_COMPLETE','persona_name'=>'Evidence Chronicler','purpose'=>'Produce attributable evidence research.','identity_constraints'=>['Chronicler only'],'competencies'=>['evidence research'],'behavioral_directives'=>['cite every claim'],'evidence_obligations'=>['preserve sources'],'explicit_exclusions'=>['no personnel selection'],'source_requirements'=>['authorized sources only'],'return_contracts'=>['sealed return'],'stop_conditions'=>['scope exceeded']];}};try{$service=new SubordinatePersonaSpecificationService($root,$gateway);$r=$service->specify($id);self::assertSame($r,$service->specify($id));self::assertSame('SEALED_PENDING_PERSONA_CONSTRUCTION',$r['status']);self::assertSame($requirements,$r['inherited_requirements']);self::assertTrue($r['persona_specification_complete']);self::assertTrue($r['construction_authority']);self::assertFalse($r['persona_selection_authority']);self::assertFalse($r['profile_approval_authority']);self::assertFalse($r['spawning_authority']);self::assertFalse($r['admission_authority']);self::assertFalse($r['execution_authority']);self::assertTrue($r['sealed']);}finally{$this->removeTree($root);}}private function removeTree(string$p):void{if(!is_dir($p))return;foreach(array_diff(scandir($p)?:[],['.','..'])as$e){$c=$p.'/'.$e;is_dir($c)?$this->removeTree($c):unlink($c);}rmdir($p);}}
